select
sites.*
from sites sites

    and sites.id = #{id}
    and sites.name like concat('%',#{name},'%')
    and sites.info = #{info}
    and sites.address = #{address}
    and sites.banner_img = #{bannerImg}
    and sites.status = #{status}
    and sites.longitude = #{longitude}
    and sites.latitude = #{latitude}
    and sites.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from sites sites

    and sites.id = #{id}
    and sites.name like concat('%',#{name},'%')
    and sites.info = #{info}
    and sites.address = #{address}
    and sites.banner_img = #{bannerImg}
    and sites.status = #{status}
    and sites.longitude = #{longitude}
    and sites.latitude = #{latitude}
    and sites.create_time = #{createTime}
